import java.util.*;

class Solution {
    public int lengthOfLongestSubstring(String s) {
        int n = s.length();
        int best = 0;

        for (int left = 0; left < n; left++) {
            Set<Character> seen = new HashSet<>();   // 每个起点都要重新开
            for (int right = left; right < n; right++) {
                char c = s.charAt(right);
                if (seen.contains(c)) break;          // 出现重复，这个起点到头了
                seen.add(c);
                best = Math.max(best, right - left + 1);
            }
        }
        return best;
    }
}

import java.util.*;

class Solution {
    public int lengthOfLongestSubstring(String s) {
        int n = s.length();
        int best = 0;
        int left = 0;
        Set<Character> window = new HashSet<>();

        for (int right = 0; right < n; right++) {
            char c = s.charAt(right);
            // 有重复就不断收缩左边界，直到重复消失（可能要移掉多个）
            while (window.contains(c)) {
                window.remove(s.charAt(left));
                left++;
            }
            window.add(c);
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

class Solution {
    public int lengthOfLongestSubstring(String s) {
        int n = s.length();
        int[] last = new int[128];
        java.util.Arrays.fill(last, -1);   // -1 表示还没出现过

        int left = 0, best = 0;
        for (int right = 0; right < n; right++) {
            char c = s.charAt(right);
            // 上次出现的位置还在窗口内，左边界直接跳到它后面一位
            // 取 max 是防止 last[c] 落在 left 左边时把 left 往回拉
            left = Math.max(left, last[c] + 1);
            last[c] = right;
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}
